const HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no\">\n<title>\ud83c\udff8 \u7fbd\u6bdb\u7403\u62a2\u573a\u795e\u5668</title>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/crypto-js/4.1.1/crypto-js.min.js\"></script>\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;500;700;900&display=swap');\n:root{\n  --bg:#07101f;--s1:#0f1d30;--s2:#162540;\n  --acc:#3b82f6;--acc2:#60a5fa;\n  --ok:#10b981;--warn:#f59e0b;--err:#ef4444;\n  --t1:#f1f5f9;--t2:#94a3b8;--bd:#1e2d45;\n  --glow:0 0 20px rgba(59,130,246,.3);\n}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nbody{font-family:'Noto Sans SC',sans-serif;background:var(--bg);color:var(--t1);min-height:100vh;padding-bottom:80px}\n\n/* header */\n.hdr{background:linear-gradient(135deg,#0a1628,#1a3a5c);padding:18px 18px 14px;border-bottom:1px solid var(--bd);position:relative;overflow:hidden}\n.hdr::after{content:'\ud83c\udff8';position:absolute;right:14px;top:12px;font-size:42px;opacity:.13}\n.hdr h1{font-size:19px;font-weight:900;letter-spacing:-.5px}\n.hdr h1 span{color:var(--acc2)}\n.hdr p{font-size:11px;color:var(--t2);margin-top:3px}\n\n/* countdown */\n.cd-box{background:var(--s1);border:1px solid var(--bd);border-radius:14px;margin:12px 14px;padding:14px;text-align:center;transition:all .3s}\n.cd-box.live{border-color:var(--acc);box-shadow:var(--glow)}\n.cd-box.soon{border-color:var(--warn);box-shadow:0 0 16px rgba(245,158,11,.35);animation:pulse .6s infinite}\n@keyframes pulse{0%,100%{opacity:1}50%{opacity:.7}}\n.cd-lbl{font-size:10px;color:var(--t2);letter-spacing:1px;margin-bottom:5px}\n.cd-num{font-size:40px;font-weight:900;letter-spacing:-3px;color:var(--acc2);font-variant-numeric:tabular-nums;line-height:1}\n.cd-num.w{color:var(--warn)}.cd-num.g{color:var(--ok)}\n.cd-sub{font-size:11px;color:var(--t2);margin-top:4px}\n.bar{height:3px;background:var(--bd);border-radius:2px;margin:9px 0 0;overflow:hidden}\n.bar-fill{height:100%;background:linear-gradient(90deg,var(--acc),var(--acc2));border-radius:2px;transition:width 1s linear}\n.cd-wake{font-size:10px;margin-top:4px;color:var(--ok)}\n\n/* target */\n.target{display:flex;align-items:center;gap:8px;margin:0 14px 7px;padding:8px 12px;background:rgba(59,130,246,.08);border:1px solid rgba(59,130,246,.2);border-radius:9px;font-size:12px;color:var(--t2)}\n.dot{width:6px;height:6px;border-radius:50%;background:var(--acc);flex-shrink:0;animation:blink 2s infinite}\n@keyframes blink{0%,100%{opacity:1}50%{opacity:.15}}\n.target b{color:var(--t1)}\n\n/* card */\n.card{margin:7px 14px;background:var(--s1);border:1px solid var(--bd);border-radius:13px;overflow:hidden}\n.card-hdr{padding:8px 13px;font-size:11px;font-weight:700;color:var(--t2);letter-spacing:.8px;border-bottom:1px solid var(--bd);display:flex;align-items:center;justify-content:space-between}\n.row{padding:11px 13px;border-bottom:1px solid var(--bd);display:flex;align-items:center;justify-content:space-between;gap:10px}\n.row:last-child{border-bottom:none}\n.row-label{font-size:13px;font-weight:500}\n.row-hint{font-size:10px;color:var(--t2);margin-top:2px}\ninput[type=time],input[type=number],textarea{background:var(--s2);border:1px solid var(--bd);border-radius:7px;color:var(--t1);padding:7px 10px;font-family:inherit;font-size:12px;outline:none;transition:border .2s}\ninput:focus,textarea:focus{border-color:var(--acc)}\ntextarea{resize:none;width:100%;margin-top:7px;font-size:10px;line-height:1.6}\n\n/* day buttons */\n.day-row{display:flex;gap:6px;padding:7px 13px 11px}\n.day-btn{flex:1;padding:8px 3px;border-radius:8px;border:2px solid var(--bd);background:var(--s2);color:var(--t2);font-family:inherit;font-size:12px;font-weight:700;cursor:pointer;text-align:center;transition:all .15s;line-height:1.5}\n.day-btn small{display:block;font-size:9px;font-weight:400;opacity:.7;margin-top:1px}\n.day-btn.on{border-color:var(--acc);background:rgba(59,130,246,.14);color:var(--acc2)}\n.day-btn.on small{opacity:1}\n\n/* people */\n.people{display:flex;gap:6px;padding:9px 13px}\n.p-btn{flex:1;padding:10px;border-radius:8px;border:2px solid var(--bd);background:var(--s2);color:var(--t2);font-family:inherit;font-size:14px;font-weight:700;cursor:pointer;transition:all .15s;text-align:center}\n.p-btn.on{border-color:var(--acc);background:rgba(59,130,246,.12);color:var(--t1)}\n\n/* presets */\n.presets{display:flex;flex-wrap:wrap;gap:5px;padding:7px 13px 9px}\n.preset-btn{padding:5px 9px;border-radius:18px;border:1px solid var(--bd);background:var(--s2);color:var(--t2);font-family:inherit;font-size:10px;font-weight:600;cursor:pointer;transition:all .15s;white-space:nowrap}\n.preset-btn:active{background:rgba(59,130,246,.15);border-color:var(--acc);color:var(--acc2)}\n.preset-btn.danger{border-color:rgba(239,68,68,.3);color:var(--err)}\n.preset-btn.query{border-color:rgba(16,185,129,.3);color:var(--ok)}\n.preset-btn.query:active{background:rgba(16,185,129,.1)}\n.preset-btn.query.loading{opacity:.6;cursor:wait}\n\n/* booking grid */\n.grid-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;padding:0 13px 8px}\n.booking-grid{border-collapse:separate;border-spacing:2px;width:100%}\n.booking-grid thead th{\n  background:var(--s2);color:var(--t2);font-size:9px;font-weight:700;\n  padding:5px 2px;border-radius:5px;text-align:center;cursor:pointer;\n  min-width:30px;user-select:none;transition:all .15s}\n.booking-grid thead th:hover{background:rgba(59,130,246,.2);color:var(--acc2)}\n.booking-grid thead th.all-on{background:var(--acc);color:#fff}\nth.th-time{min-width:76px;width:76px;background:transparent !important;cursor:default;font-size:9px;color:var(--t2);text-align:right}\n\n/* time row label */\n.time-label{\n  font-size:9px;color:var(--t2);text-align:right;\n  padding:3px 5px 3px 0;cursor:pointer;user-select:none;\n  white-space:nowrap;transition:color .15s;border-radius:4px;\n  vertical-align:middle}\n.time-label:hover{color:var(--acc2)}\n.time-label.row-on{color:var(--acc2);font-weight:700}\n\n/* slot cells */\n.slot{\n  height:32px;border-radius:5px;cursor:pointer;transition:all .12s;\n  position:relative;user-select:none;text-align:center;vertical-align:middle;\n  font-size:9px;font-weight:700;line-height:32px}\n/* price tiers */\n.slot.cheap{background:#f8fafc;border:1px solid #94a3b8;color:#1e293b;font-size:11px}\n.slot.exp{background:#f8fafc;border:1px solid #64748b;color:#1e293b;font-size:11px}\n/* closed (no availability) */\n.slot.closed{background:#111827;border:1px solid #1f2937;color:#374151;cursor:not-allowed;opacity:.5}\n.slot.closed::after{content:'\u2715';font-size:11px}\n/* booked */\n.slot.booked{background:#7f1d1d;border:1px solid #991b1b;color:#fca5a5;cursor:not-allowed;font-size:11px}\n\n.toast{position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:9999;padding:12px 24px;border-radius:12px;font-size:14px;font-weight:700;color:#fff;opacity:0;transition:opacity .3s;pointer-events:none}.toast.show{opacity:1}.toast.ok{background:#059669}.toast.er{background:#dc2626}.toast.wn{background:#d97706}\n/* selected */\n.slot.on{background:var(--acc) !important;border-color:var(--acc) !important;color:#fff !important;box-shadow:0 0 6px rgba(59,130,246,.5)}\n.slot.on::after{content:'\u2713';font-size:12px;font-weight:900}\n.slot:not(.closed):not(.booked):active{transform:scale(.88)}\n\n/* summary */\n.summary{padding:7px 13px;font-size:11px;color:var(--t2);display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--bd)}\n.summary b{color:var(--acc2)}\n.summary .price{color:var(--ok);font-weight:700;font-size:13px}\n\n/* legend */\n.legend{display:flex;gap:10px;padding:4px 13px 8px;font-size:9px;color:var(--t2)}\n.leg{display:flex;align-items:center;gap:4px}\n.leg-dot{width:10px;height:10px;border-radius:3px;flex-shrink:0}\n.leg-dot.cheap{background:#f8fafc;border:1px solid #94a3b8}\n.leg-dot.exp{background:#f8fafc;border:1px solid #64748b}\n.leg-dot.on{background:var(--acc)}\n.leg-dot.closed{background:#111827;border:1px solid #1f2937}\n.leg-dot.booked{background:#7f1d1d;border:1px solid #991b1b}\n\n/* buttons */\n.btn-go{display:block;width:calc(100% - 28px);margin:8px 14px;padding:14px;background:linear-gradient(135deg,#1d4ed8,#3b82f6);border:none;border-radius:12px;color:#fff;font-family:inherit;font-size:15px;font-weight:700;cursor:pointer;transition:all .2s;text-align:center;box-shadow:0 4px 14px rgba(59,130,246,.3)}\n.btn-go:active{transform:scale(.98)}\n.btn-go.disarm{background:linear-gradient(135deg,#dc2626,#ef4444);box-shadow:0 4px 14px rgba(239,68,68,.3)}\n.btn-test{display:block;width:calc(100% - 28px);margin:0 14px 8px;padding:12px;background:transparent;border:1px solid var(--bd);border-radius:12px;color:var(--t2);font-family:inherit;font-size:13px;font-weight:500;cursor:pointer;text-align:center}\n.btn-test:active{background:var(--s2)}\n\n/* log */\n.logbox{margin:7px 14px;background:#040810;border:1px solid var(--bd);border-radius:10px;padding:10px;font-family:'Courier New',monospace;font-size:10px;line-height:1.9;max-height:180px;overflow-y:auto;color:#475569}\n.logbox .ok{color:var(--ok)}.logbox .er{color:var(--err)}.logbox .inf{color:var(--acc2)}.logbox .wn{color:var(--warn)}\n\n/* notice */\n.notice{margin:0 14px 7px;padding:9px 12px;background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.2);border-radius:8px;font-size:11px;color:#fbbf24;line-height:1.7}\n.notice b{display:block;margin-bottom:2px}\n</style>\n</head>\n<body>\n<div id=\"toast\" class=\"toast\"></div>\n\n<div class=\"hdr\">\n  <h1>\ud83c\udff8 \u7fbd\u6bdb\u7403<span>\u62a2\u573a\u795e\u5668</span></h1>\n  <p>\u4e2d\u56fd\u5730\u8d28\u5927\u5b66\uff08\u5317\u4eac\uff09\u00b7 \u667a\u80fd\u5b9a\u65f6\u9884\u7ea6 v18.0 \u00b7 \u53ef\u89c6\u5316\u9009\u573a</p>\n</div>\n\n<!-- Countdown -->\n<div class=\"cd-box\" id=\"cdBox\">\n  <div class=\"cd-lbl\" id=\"cdLbl\">\u8ddd\u79bb\u5f00\u653e\u8fd8\u6709</div>\n  <div class=\"cd-num\" id=\"cdNum\">--:--:--</div>\n  <div class=\"cd-sub\" id=\"cdSub\">\u8ba1\u7b97\u4e2d...</div>\n  <div class=\"bar\"><div class=\"bar-fill\" id=\"barFill\" style=\"width:0\"></div></div>\n  <div class=\"cd-wake\" id=\"cdWake\"></div>\n</div>\n\n<!-- Target -->\n<div class=\"target\"><div class=\"dot\"></div><span id=\"targetTxt\">\u8bf7\u5728\u683c\u5b50\u91cc\u9009\u573a\u5730\u548c\u65f6\u95f4</span></div>\n\n<!-- Date/Time config -->\n<div class=\"card\">\n  <div class=\"card-hdr\"><span>\ud83d\udcc5 \u9884\u7ea6\u914d\u7f6e</span></div>\n  <div style=\"padding:6px 13px 2px;font-size:10px;color:var(--t2)\">\u9884\u7ea6\u54ea\u5929\uff08\u4eca\u5929 / \u660e\u5929 / \u540e\u5929\uff09</div>\n  <div class=\"day-row\">\n    <button class=\"day-btn\" id=\"d1\" onclick=\"setDay(0)\">\u4eca\u5929<small id=\"d1lbl\"></small></button>\n    <button class=\"day-btn\" id=\"d2\" onclick=\"setDay(1)\">\u660e\u5929<small id=\"d2lbl\"></small></button>\n    <button class=\"day-btn on\" id=\"d3\" onclick=\"setDay(2)\">\u540e\u5929<small id=\"d3lbl\"></small></button>\n    \n  </div>\n  <div class=\"row\">\n    <div><div class=\"row-label\">\u5f00\u653e\u65f6\u95f4</div><div class=\"row-hint\">\u5230\u70b9\u81ea\u52a8\u5e76\u53d1\u53d1\u8bf7\u6c42</div></div>\n    <input type=\"time\" id=\"openTime\" value=\"07:30\" style=\"width:100px\" oninput=\"startTick()\">\n  </div>\n  <div class=\"row\">\n    <div><div class=\"row-label\">\u63d0\u524d\u89e6\u53d1</div><div class=\"row-hint\">\u8865\u507f\u7f51\u7edc\u5ef6\u8fdf ms</div></div>\n    <input type=\"number\" id=\"leadMs\" value=\"200\" min=\"0\" max=\"3000\" style=\"width:80px;text-align:center\">\n  </div>\n</div>\n\n<!-- Grid -->\n<div class=\"card\">\n  <div class=\"card-hdr\">\n    <span>\ud83c\udfdf\ufe0f \u573a\u5730 \u00d7 \u65f6\u95f4</span>\n    <span id=\"userName\" style=\"font-size:16px;color:var(--ok);font-weight:700\"></span>\n    <span style=\"font-size:9px;font-weight:400;color:var(--t2)\">\u70b9\u65f6\u95f4\u884c=\u6574\u884c \u00b7 \u70b9\u573a\u5730=\u6574\u5217</span>\n  </div>\n  <div class=\"presets\">\n    <button class=\"preset-btn query\" id=\"queryBtn\" onclick=\"queryAvailability()\">\ud83d\udd0d \u67e5\u8be2\u7a7a\u4f4d</button>\n    <button class=\"preset-btn\" onclick=\"quickSelect('09:00','12:00')\">\u4e0a\u534809-12</button>\n    <button class=\"preset-btn\" onclick=\"quickSelect('12:00','14:00')\">\u4e2d\u534812-14</button>\n    <button class=\"preset-btn\" onclick=\"quickSelect('14:00','18:00')\">\u4e0b\u534814-18</button>\n    <button class=\"preset-btn\" onclick=\"quickSelect('18:00','22:00')\">\u665a\u4e0a18-22</button>\n    <button class=\"preset-btn danger\" onclick=\"clearAll()\">\u2715 \u6e05\u7a7a</button>\n  </div>\n  <div class=\"grid-wrap\">\n    <table class=\"booking-grid\" id=\"bookingGrid\">\n      <thead><tr id=\"gridHead\"></tr></thead>\n      <tbody id=\"gridBody\"></tbody>\n    </table>\n  </div>\n  <!-- Legend -->\n  <div class=\"legend\">\n    <div class=\"leg\"><div class=\"leg-dot cheap\"></div>\u00a510 \u5de5\u4f5c\u65e5\u767d\u5929</div>\n    <div class=\"leg\"><div class=\"leg-dot exp\"></div>\u00a540 \u5176\u4ed6\u65f6\u6bb5</div>\n    <div class=\"leg\"><div class=\"leg-dot on\"></div>\u5df2\u9009</div>\n    <div class=\"leg\"><div class=\"leg-dot booked\"></div>\u5df2\u6ee1</div>\n    <div class=\"leg\"><div class=\"leg-dot closed\"></div>\u4e0d\u5f00\u653e</div>\n  </div>\n  <div class=\"summary\">\n    <span>\u5df2\u9009 <b id=\"selCount\">0</b> \u683c \u00b7 <b id=\"selCourts\">0</b> \u573a \u00d7 <b id=\"selTimes\">0</b> \u6bb5</span>\n    <span class=\"price\" id=\"selPrice\">\u00a50</span>\n  </div>\n</div>\n\n<!-- People -->\n<div class=\"card\">\n  <div class=\"card-hdr\"><span>\ud83d\udc65 \u540c\u884c\u4eba\u6570</span></div>\n  <div class=\"people\">\n    <button class=\"p-btn\" id=\"p3\" onclick=\"pickPeople(3)\">3\u4eba</button>\n    <button class=\"p-btn\" id=\"p4\" onclick=\"pickPeople(4)\">4\u4eba</button>\n    <button class=\"p-btn on\" id=\"p5\" onclick=\"pickPeople(5)\">5\u4eba</button>\n  </div>\n</div>\n\n<!-- Token -->\n<div class=\"card\">\n  <div class=\"card-hdr\"><span>\ud83d\udd11 \u8eab\u4efd\u4ee4\u724c</span></div>\n  <div id=\"tokenArea\" class=\"row\" style=\"flex-direction:column;align-items:flex-start\">\n    <div style=\"font-size:10px;color:var(--t2)\">\u4f01\u4e1a\u5fae\u4fe1\u6293\u5305 \u2192 \u627e\u8bf7\u6c42\u5934 token \u5b57\u6bb5 \u00b7 \u81ea\u52a8\u4fdd\u5b58</div>\n    <textarea id=\"token\" rows=\"4\" placeholder=\"\u7c98\u8d34 token...\"></textarea>\n  </div>\n  <div style=\"margin-top:6px;display:flex;gap:8px\">\n    <button class=\"btn-go\" style=\"flex:1;padding:8px;font-size:13px\" onclick=\"wxLogin()\">\ud83d\udd11 openid\u767b\u5f55</button>\n    <button class=\"btn-go\" style=\"flex:1;padding:8px;font-size:13px;background:#374151\" onclick=\"toggleTokenArea()\" id=\"tokenToggle\">\u25bc \u9690\u85cfToken</button>\n  </div>\n</div>\n\n<div class=\"notice\">\n  <b>\u26a0\ufe0f \u4f7f\u7528\u6d41\u7a0b</b>\n  \u2460 \u586b Token \u2192 \u9009\u65e5\u671f \u2192 \u70b9\u300c\u67e5\u8be2\u7a7a\u4f4d\u300d\u770b\u54ea\u4e9b\u683c\u5b50\u53ef\u9884\u7ea6<br>\n  \u2461 \u5728\u7eff/\u6a59\u683c\u5b50\u4e0a\u70b9\u9009 \u2192 \u542f\u52a8\u5b9a\u65f6 \u2192 7:30 \u81ea\u52a8\u5e76\u53d1\u62a2<br>\n  \u2462 \u6536\u5230\u6210\u529f\u63d0\u793a\u540e\u7acb\u523b\uff1a<b>\u6ed1\u52a8\u9a8c\u8bc1\u7801</b> + <b>\u652f\u4ed8\u5bc6\u7801</b><br>\n  \u2463 \u5de5\u4f5c\u65e509-18\u65f6\u00a510/\u573a\u00b7\u5c0f\u65f6\uff0c\u5176\u4f59\u65f6\u6bb5\u00a540\n</div>\n\n<button class=\"btn-go\" id=\"armBtn\" onclick=\"toggleArm()\">\ud83d\ude80 \u542f\u52a8\u5b9a\u65f6\u62a2\u573a</button>\n<button class=\"btn-test\" onclick=\"fireNow()\">\u26a1 \u7acb\u5373\u6d4b\u8bd5\uff08\u4e0d\u7b497:30\uff09</button>\n\n<div class=\"card\">\n  <div class=\"card-hdr\"><span>\ud83d\udccb \u8fd0\u884c\u65e5\u5fd7</span></div>\n  <div class=\"logbox\" id=\"log\"><span style=\"color:#334155\">\u7b49\u5f85\u64cd\u4f5c...</span></div>\n</div>\n\n<script>\nconst VENUE_ID = '889772856316272640';\nconst PROXY    = 'https://aoongu.qzz.io';\nconst API_BOOK = '/service/appointment/appointment/phone/createBookingBytime';\nconst API_QUERY = '/service/appointment/appointment/phone/bookingByTime';\nconst WEEKDAYS = ['\\u65e5','\\u4e00','\\u4e8c','\\u4e09','\\u56db','\\u4e94','\\u516d'];\n\nlet D = {\n  courts: {},\n  courtOrder: [],\n  times: [],\n  allTimes: [],\n  slotIdx: {},\n  timeList: [],\n  priceMap: {},\n  loaded: false,\n};\n\nfunction toggleTokenArea() {\n  const ta = document.getElementById('tokenArea');\n  const toggle = document.getElementById('tokenToggle');\n  if (ta.style.display === 'none') {\n    ta.style.display = '';\n    toggle.textContent = '\u25bc \u9690\u85cfToken';\n  } else {\n    ta.style.display = 'none';\n    toggle.textContent = '\u25b2 \u663e\u793aToken';\n  }\n}\n\nasync function wxLoginAuto(openid) {\n  log('inf', '\ud83d\udd11 \u81ea\u52a8\u767b\u5f55...');\n  try {\n    const payload = aesEncrypt({ openid, orgid: '2' });\n    const res = await fetch(PROXY + '/service/appointment/appointment/phone/login/wxLogin', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ item: payload })\n    });\n    const raw = await res.text();\n    let data = {};\n    try { data = JSON.parse(raw); } catch(_) {}\n    let parsed = data;\n    if (data.item) {\n      try { parsed = JSON.parse(aesDecrypt(data.item)); } catch(_) { parsed = data; }\n    }\n    if (parsed.success !== false && parsed.resultData) {\n      const token = parsed.resultData.token || parsed.resultData;\n      const name = parsed.resultData.name || '';\n      if (typeof token === 'string' && token.length > 10) {\n        document.getElementById('token').value = token;\n        localStorage.setItem('cugb_token', token);\n        if (name) {\n          document.getElementById('userName').textContent = name;\n          localStorage.setItem('cugb_name', name);\n        }\n        log('ok', '\u2705 \u81ea\u52a8\u767b\u5f55\u6210\u529f\uff01Token\u5df2\u586b\u5165');\n        fetchSchedule();\n        return;\n      }\n    }\n    log('er', '\u274c \u81ea\u52a8\u767b\u5f55\u5931\u8d25\uff0c\u8bf7\u624b\u52a8\u767b\u5f55');\n  } catch(e) {\n    log('er', '\u274c \u81ea\u52a8\u767b\u5f55\u5f02\u5e38: ' + e.message);\n  }\n}\n\nasync function wxLogin() {\n  const input = prompt('\u8bf7\u7c98\u8d34\u6293\u5305\u83b7\u5f97\u7684\u52a0\u5bc6\u5b57\u7b26\u4e32\uff08\u5982 {\"item\":\"75A6...\"}\uff09\u6216\u76f4\u63a5\u8f93\u5165openid:');\n  if (!input) return;\n  log('inf', '\ud83d\udd11 \u5c1d\u8bd5\u767b\u5f55...');\n  try {\n    let openid = '';\n    const trimmed = input.trim();\n    if (trimmed.startsWith('{')) {\n      try {\n        const obj = JSON.parse(trimmed);\n        if (obj.item) {\n          const dec = aesDecrypt(obj.item);\n          const parsed = JSON.parse(dec);\n          openid = parsed.openid || '';\n          log('inf', '\u2705 \u81ea\u52a8\u89e3\u5bc6\u83b7\u5f97openid');\n        }\n      } catch(e) { log('er', '\u89e3\u5bc6\u5931\u8d25: ' + e.message); return; }\n    } else {\n      openid = trimmed;\n    }\n    if (!openid) { log('er', '\u672a\u83b7\u5f97openid'); return; }\n    localStorage.setItem('cugb_openid', openid);\n    const payload = aesEncrypt({ openid, orgid: '2' });\n    const res = await fetch(PROXY + '/service/appointment/appointment/phone/login/wxLogin', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ item: payload })\n    });\n    const raw = await res.text();\n    let data = {};\n    try { data = JSON.parse(raw); } catch(_) {}\n    let parsed = data;\n    if (data.item) {\n      try { parsed = JSON.parse(aesDecrypt(data.item)); } catch(_) { parsed = data; }\n    }\n    if (parsed.success !== false && parsed.resultData) {\n      const token = parsed.resultData.token || parsed.resultData;\n      const name = parsed.resultData.name || '';\n      if (typeof token === 'string' && token.length > 10) {\n        document.getElementById('token').value = token;\n        localStorage.setItem('cugb_token', token);\n        if (name) {\n          document.getElementById('userName').textContent = name;\n          localStorage.setItem('cugb_name', name);\n        }\n        log('ok', '\u2705 \u767b\u5f55\u6210\u529f\uff01Token\u5df2\u81ea\u52a8\u586b\u5165');\n        showToast('ok', '\u2705 \u767b\u5f55\u6210\u529f\uff01', 2000);\n        toggleTokenArea();\n        fetchSchedule();\n        return;\n      }\n    }\n    log('er', '\u274c \u767b\u5f55\u5931\u8d25\uff0c\u8bf7\u68c0\u67e5\u8f93\u5165\u6216\u624b\u52a8\u586b\u5199Token');\n    showToast('er', '\u274c \u767b\u5f55\u5931\u8d25');\n  } catch(e) {\n    log('er', '\u274c \u767b\u5f55\u5f02\u5e38: ' + e.message);\n  }\n}\n\nasync function fetchSchedule() {\n  let token = document.getElementById('token').value.trim();\n  if (!token) return;\n\n  const date = fmt(targetDate());\n  const btn = document.getElementById('queryBtn');\n  btn.textContent = '\\ud83d\\udd04 \\u52a0\\u8f7d\\u4e2d...';\n  btn.classList.add('loading');\n  D.loaded = false; D.priceMap = {}; bookedSet.clear(); closedSet.clear(); selected.clear(); buildGrid();\n\n  try {\n    const rawObj = { nodeid: VENUE_ID, selectdate: date }; const payload = aesEncrypt(rawObj); \n    const t0=Date.now(); const res = await fetch(PROXY + API_QUERY, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json', token },\n      body: JSON.stringify({ item: payload })\n    });\n    const raw = await res.text();\n    if (raw.trimStart().startsWith('<')) {\n      log('wn', '\\u26a0\\ufe0f Token\\u53ef\\u80fd\\u5931\\u6548\\uff0c\\u5c1d\\u8bd5\\u91cd\\u65b0\\u767b\\u5f55...');\n      const openid = localStorage.getItem('cugb_openid');\n      if (openid) {\n        await wxLoginAuto(openid);\n        const newToken = document.getElementById('token').value.trim();\n        if (newToken && newToken !== token) {\n          const retryRes = await fetch(PROXY + API_QUERY, {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json', token: newToken },\n            body: JSON.stringify({ item: payload })\n          });\n          const retryRaw = await retryRes.text();\n          if (!retryRaw.trimStart().startsWith('<')) {\n            let retryData = {};\n            try { retryData = JSON.parse(retryRaw); } catch(_) {}\n            if (retryData.success === true && retryData.resultData) {\n              applySchedule(retryData.resultData);\n              const ms2 = Date.now() - t0;\n              log('ok', '\\u2705 \\u91cd\\u767b\\u6210\\u529f\\uff01\\u5df2\\u52a0\\u8f7d ' + date + ' \\u573a\\u6b21\\u6570\\u636e (' + ms2 + 'ms)');\n            }\n          }\n        }\n      }\n      return;\n    }\n    let data = {};\n    try { data = JSON.parse(raw); } catch(_) {}\n\n    if (data.success === true && data.resultData) {\n      applySchedule(data.resultData);\n      const ms = Date.now() - t0; log('ok', `\\u2705 \\u5df2\\u52a0\\u8f7d ${date} \\u573a\\u6b21\\u6570\\u636e\\uff1a${D.courtOrder.length}\\u4e2a\\u573a\\u5730\\uff0c${D.times.length}\\u4e2a\\u65f6\\u95f4\\u6bb5 (${ms}ms)`);\n    } else {\n      const ms2=Date.now()-t0; log('wn', '\\u26a0\\ufe0f \\u67e5\\u8be2\\u672a\\u8fd4\\u56de\\u6709\\u6548\\u6570\\u636e: HTTP'+res.status+' ('+ms2+'ms) \\u2192 '+raw.substring(0,400));\n    }\n  } catch(e) {\n    log('er', '\\u274c \\u67e5\\u8be2\\u5931\\u8d25: ' + e.message);\n  }\n\n  btn.textContent = '\\ud83d\\udd0d \\u67e5\\u8be2\\u7a7a\\u4f4d';\n  btn.classList.remove('loading');\n}\n\nfunction applySchedule(rd) {\n  D.courts = {};\n  D.courtOrder = [];\n  D.times = [];\n  D.allTimes = [];\n  D.slotIdx = {};\n  D.timeList = rd.timeList || [];\n  D.priceMap = {};\n\n  (rd.nodeList || []).forEach((n, i) => {\n    D.courts[n.sitename] = n.nodeid;\n    D.courtOrder.push(n.sitename);\n  });\n\n  (rd.timeList || []).forEach((t, i) => {\n    D.allTimes.push(t.time);\n    D.slotIdx[t.time] = i;\n    if (t.status === '0') D.times.push(t.time);\n  });\n\n  (rd.priceList || []).forEach(p => {\n    D.priceMap[p.y + '-' + p.x] = parseInt(p.price) * 100;\n  });\n\n  D.loaded = true;\n  selected.clear();\n  closedSet.clear();\n  bookedSet.clear();\n\n  (rd.conflictList || []).forEach(item => {\n    const parts = item.split('-');\n    const courtIdx = parseInt(parts[0]);\n    const timeIdx = parseInt(parts[1]);\n    const courtName = D.courtOrder[courtIdx];\n    const timeStr = D.allTimes[timeIdx];\n    if (courtName && timeStr) bookedSet.add(courtName + '-' + timeStr);\n  });\n\n  buildGrid();\n  updateSummary();\n}\n\nfunction slotPrice(dayOffset, startTime) {\n  const d = new Date();\n  d.setDate(d.getDate() + dayOffset);\n  const dow  = d.getDay();\n  const isWD = dow >= 1 && dow <= 5;\n  const h    = parseInt(startTime);\n  return (isWD && h >= 9 && h < 18) ? 1000 : 4000;\n}\n\nfunction getSlotFen(courtIdx, timeIdx) {\n  const key = courtIdx + '-' + timeIdx;\n  if (!(key in D.priceMap)) return -1;\n  return D.priceMap[key];\n}\n\nconst AES_KEY = CryptoJS.enc.Utf8.parse('0102030405060708');\nconst AES_IV  = CryptoJS.enc.Utf8.parse('0102030405060708');\nfunction aesEncrypt(obj) {\n  const plain = CryptoJS.enc.Utf8.parse(JSON.stringify(obj));\n  const enc   = CryptoJS.AES.encrypt(plain, AES_KEY, {\n    iv: AES_IV, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7\n  });\n  return enc.ciphertext.toString().toUpperCase();\n}\n\nfunction aesDecrypt(hexStr) {\n  const cipherParams = CryptoJS.lib.CipherParams.create({\n    ciphertext: CryptoJS.enc.Hex.parse(hexStr)\n  });\n  const dec = CryptoJS.AES.decrypt(cipherParams, AES_KEY, {\n    iv: AES_IV, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7\n  });\n  return dec.toString(CryptoJS.enc.Utf8);\n}\n\nconst S = {\n  people: 5, dayOffset: 2,\n  armed: false, firing: false, tick: null\n};\nconst selected = new Set();\nconst closedSet = new Set();\nconst bookedSet = new Set();\n\nfunction buildGrid() {\n  const head = document.getElementById('gridHead');\n  const body = document.getElementById('gridBody');\n  const courts = D.loaded ? D.courtOrder : [];\n  const allTimes = D.loaded ? D.allTimes : [];\n  const timeList = D.loaded ? D.timeList : [];\n\n  let hHTML = '<th class=\"th-time\"></th>';\n  courts.forEach(c => {\n    hHTML += `<th id=\"ch_${c}\" onclick=\"toggleCourt('${c}')\">${c}</th>`;\n  });\n  head.innerHTML = hHTML;\n  body.innerHTML = '';\n\n  allTimes.forEach((t, ti) => {\n    if (ti >= allTimes.length - 1) return;\n    const tInfo = timeList[ti] || {};\n    const isClosed = tInfo.status === '1';\n    const nextT = allTimes[ti + 1];\n    const tid = t.replace(':', '');\n    const tr = document.createElement('tr');\n    const labelTxt = parseInt(t) + '-' + parseInt(nextT);\n    let rHTML = `<td class=\"time-label\" id=\"tl_${tid}\" onclick=\"toggleTime('${t}')\">${labelTxt}</td>`;\n    courts.forEach((c, ci) => {\n      const timeIdx = ti;\n      const fen = D.loaded ? getSlotFen(ci, timeIdx) : slotPrice(S.dayOffset, t);\n      const isBooked = bookedSet.has(c + '-' + t);\n      let cellClass, cellLabel;\n      if (isClosed) {\n        cellClass = 'closed'; cellLabel = '';\n      } else if (fen === -1 || isBooked) {\n        cellClass = 'booked';\n        if (isBooked && fen > 0) { cellLabel = '\u00a5' + (fen / 100); } else { cellLabel = ''; }\n      } else {\n        cellClass = fen === 1000 ? 'cheap' : 'exp';\n        cellLabel = '\u00a5' + (fen / 100);\n      }\n      const onclick = (isClosed || fen === -1 || isBooked) ? '' : `onclick=\"toggleCell('${c}','${t}')\"`;\n      rHTML += `<td class=\"slot ${cellClass}\" id=\"slot_${c}_${tid}\"\n        ${onclick} data-fen=\"${fen}\">${cellLabel}</td>`;\n    });\n    tr.innerHTML = rHTML;\n    body.appendChild(tr);\n  });\n}\n\nfunction refreshPriceClasses() {\n  const courts = D.loaded ? D.courtOrder : [];\n  const times  = D.loaded ? D.times : [];\n  times.forEach(t => {\n    const tid = t.replace(':', '');\n    courts.forEach((c, ci) => {\n      const cell = document.getElementById(`slot_${c}_${tid}`);\n      if (!cell) return;\n      const timeIdx = D.slotIdx[t];\n      const fen = D.loaded ? getSlotFen(ci, timeIdx) : slotPrice(S.dayOffset, t);\n      const pClass = fen === 1000 ? 'cheap' : 'exp';\n      const pLabel = fen === 1000 ? '10' : '40';\n      cell.dataset.fen = fen;\n      cell.classList.remove('cheap', 'exp');\n      if (!cell.classList.contains('booked') && !cell.classList.contains('closed'))\n        cell.classList.add(pClass);\n      if (!cell.classList.contains('on') && !cell.classList.contains('booked') && !cell.classList.contains('closed'))\n        cell.textContent = pLabel;\n    });\n  });\n}\n\nfunction toggleCell(court, time, forceState) {\n  const key  = court + '-' + time;\n  const tid  = time.replace(':', '');\n  const cell = document.getElementById(`slot_${court}_${tid}`);\n  if (!cell) return;\n  if (cell.classList.contains('closed') || cell.classList.contains('booked')) return;\n\n  let isOn;\n  if      (forceState === true)  { selected.add(key);    isOn = true;  }\n  else if (forceState === false) { selected.delete(key); isOn = false; }\n  else if (selected.has(key))    { selected.delete(key); isOn = false; }\n  else                           { selected.add(key);    isOn = true;  }\n\n  cell.classList.toggle('on', isOn);\n  if (!isOn) {\n    const fen    = parseInt(cell.dataset.fen || '4000');\n    cell.textContent = fen === 1000 ? '10' : '40';\n  }\n  updateSummary();\n}\n\nfunction toggleTime(time) {\n  const courts = D.loaded ? D.courtOrder : [];\n  const available = courts.filter(c => {\n    const cell = document.getElementById(`slot_${c}_${time.replace(':','')}`);\n    return cell && !cell.classList.contains('closed') && !cell.classList.contains('booked');\n  });\n  const allOn = available.every(c => selected.has(c + '-' + time));\n  available.forEach(c => toggleCell(c, time, !allOn));\n}\n\nfunction toggleCourt(court) {\n  const times = D.loaded ? D.times : [];\n  const available = times.filter(t => {\n    const cell = document.getElementById(`slot_${court}_${t.replace(':','')}`);\n    return cell && !cell.classList.contains('closed') && !cell.classList.contains('booked');\n  });\n  const allOn = available.every(t => selected.has(court + '-' + t));\n  available.forEach(t => toggleCell(court, t, !allOn));\n}\n\nfunction quickSelect(startTime, endTime) {\n  const courts = D.loaded ? D.courtOrder : [];\n  const times = D.loaded ? D.times : [];\n  const range = times.filter(t => t >= startTime && t < endTime);\n  const avail = [];\n  range.forEach(t => courts.forEach(c => {\n    const cell = document.getElementById(`slot_${c}_${t.replace(':','')}`);\n    if (cell && !cell.classList.contains('closed') && !cell.classList.contains('booked'))\n      avail.push({c, t});\n  }));\n  const allOn = avail.every(({c, t}) => selected.has(c + '-' + t));\n  avail.forEach(({c, t}) => toggleCell(c, t, !allOn));\n}\n\nfunction clearAll() {\n  [...selected].forEach(key => {\n    selected.delete(key);\n    const dash  = key.indexOf('-');\n    const court = key.slice(0, dash);\n    const time  = key.slice(dash + 1);\n    const cell  = document.getElementById(`slot_${court}_${time.replace(':','')}`);\n    if (cell) {\n      cell.classList.remove('on');\n      const fen = parseInt(cell.dataset.fen || '4000');\n      cell.textContent = fen === 1000 ? '10' : '40';\n    }\n  });\n  updateSummary();\n}\n\nfunction updateSummary() {\n  const courts = D.loaded ? D.courtOrder : [];\n  const times  = D.loaded ? D.times : [];\n  const selCourts = new Set([...selected].map(k => k.split(/-(.+)/)[0]));\n  const selTimes  = new Set([...selected].map(k => k.split(/-(.+)/)[1]));\n  const count  = selected.size;\n  let totalFen = 0;\n  for (const key of selected) {\n    const dash  = key.indexOf('-');\n    const court = key.slice(0, dash);\n    const time  = key.slice(dash + 1);\n    const cell  = document.getElementById(`slot_${court}_${time.replace(':','')}`);\n    totalFen   += cell ? parseInt(cell.dataset.fen || '4000') : 4000;\n  }\n  document.getElementById('selCount').textContent  = count;\n  document.getElementById('selCourts').textContent = selCourts.size;\n  document.getElementById('selTimes').textContent  = selTimes.size;\n  document.getElementById('selPrice').textContent  = count ? '\\u00a5' + (totalFen / 100) : '\\u00a50';\n\n  courts.forEach(c => {\n    const avail  = times.filter(t => {\n      const cell = document.getElementById(`slot_${c}_${t.replace(':','')}`);\n      return cell && !cell.classList.contains('closed') && !cell.classList.contains('booked');\n    });\n    const th = document.getElementById('ch_' + c);\n    if (th) th.classList.toggle('all-on', avail.length > 0 && avail.every(t => selected.has(c + '-' + t)));\n  });\n  times.forEach(t => {\n    const avail  = courts.filter(c => {\n      const cell = document.getElementById(`slot_${c}_${t.replace(':','')}`);\n      return cell && !cell.classList.contains('closed') && !cell.classList.contains('booked');\n    });\n    const td = document.getElementById('tl_' + t.replace(':',''));\n    if (td) td.classList.toggle('row-on', avail.length > 0 && avail.every(c => selected.has(c + '-' + t)));\n  });\n\n  updateTarget();\n}\n\nasync function queryAvailability() {\n  let token = document.getElementById('token').value.trim();\n  if (!token) {\n    const openid = localStorage.getItem('cugb_openid');\n    if (openid) {\n      log('inf', '\\ud83d\\udd11 Token\\u4e3a\\u7a7a\\uff0c\\u5c1d\\u8bd5openid\\u81ea\\u52a8\\u767b\\u5f55...');\n      await wxLoginAuto(openid);\n      token = document.getElementById('token').value.trim();\n    }\n    if (!token) { log('er', '\\u274c \\u8bf7\\u5148\\u767b\\u5f55\\uff01'); return; }\n  }\n  await fetchSchedule();\n}\n\nconst p2  = n => String(n).padStart(2, '0');\nconst fmt = d => `${d.getFullYear()}-${p2(d.getMonth()+1)}-${p2(d.getDate())}`;\nfunction targetDate() {\n  const d = new Date(); d.setDate(d.getDate() + S.dayOffset); return d;\n}\n\nfunction setDay(n) {\n  S.dayOffset = n;\n  const offsets = [0,1,2,3];\n  [1,2,3,4].forEach((i,idx) => document.getElementById('d'+i).classList.toggle('on', offsets[idx]===n));\n  selected.clear();\n  closedSet.clear();\n  bookedSet.clear();\n  if (D.loaded) {\n    buildGrid();\n    refreshPriceClasses();\n  }\n  updateSummary();\n  updateTarget();\n  if (document.getElementById('token').value.trim()) {\n    fetchSchedule();\n  } else {\n    const openid = localStorage.getItem('cugb_openid');\n    if (openid) wxLoginAuto(openid);\n  }\n}\n\nfunction initDayLabels() {\n  [0,1,2,3].forEach((offset, idx) => {\n    const d = new Date(); d.setDate(d.getDate() + offset);\n    document.getElementById('d'+(idx+1)+'lbl').textContent =\n      `${p2(d.getMonth()+1)}/${p2(d.getDate())} \\u5468${WEEKDAYS[d.getDay()]}`;\n  });\n}\n\nfunction pickPeople(n) {\n  S.people = n;\n  [3,4,5].forEach(i => document.getElementById('p'+i).classList.toggle('on', i===n));\n}\n\nfunction updateTarget() {\n  const d      = targetDate();\n  const cnt    = selected.size;\n  const courts = new Set([...selected].map(k => k.split(/-(.+)/)[0]));\n  const times  = new Set([...selected].map(k => k.split(/-(.+)/)[1]));\n  document.getElementById('targetTxt').innerHTML = cnt\n    ? `\\u62a2 <b>${fmt(d)}</b>\\uff08+${S.dayOffset}\\uff09\\u00b7 <b>${courts.size}</b>\\u4e2a\\u573a \\u00b7 <b>${times.size}</b>\\u4e2a\\u65f6\\u6bb5`\n    : `\\u62a2 <b>${fmt(d)}</b>\\uff08+${S.dayOffset}\\uff09\\u00b7 \\u8bf7\\u9009\\u683c\\u5b50\\u6216\\u5148\\u67e5\\u8be2\\u7a7a\\u4f4d`;\n}\n\nlet wakeLock = null;\n\nasync function acquireWakeLock() {\n  if (!('wakeLock' in navigator)) return;\n  try {\n    wakeLock = await navigator.wakeLock.request('screen');\n    document.getElementById('cdWake').textContent = '\\ud83d\\udd06 \\u5c4f\\u5e55\\u5e38\\u4eae\\u5df2\\u9501\\u5b9a';\n    wakeLock.addEventListener('release', () => {\n      document.getElementById('cdWake').textContent = '';\n      wakeLock = null;\n    });\n  } catch(e) {\n    document.getElementById('cdWake').textContent = '\\u26a0\\ufe0f \\u8bf7\\u624b\\u52a8\\u4fdd\\u6301\\u5c4f\\u5e55\\u4eae\\u8d77';\n  }\n}\n\nfunction releaseWakeLock() {\n  if (wakeLock) { wakeLock.release(); wakeLock = null; }\n  document.getElementById('cdWake').textContent = '';\n}\n\ndocument.addEventListener('visibilitychange', () => {\n  if (document.hidden) return;\n  const now    = new Date();\n  const parts  = document.getElementById('openTime').value.split(':');\n  const lead   = parseInt(document.getElementById('leadMs').value) || 0;\n  const target = new Date();\n  target.setHours(+parts[0], +parts[1], 0, 0);\n  const diff = target - now - lead;\n  if (diff <= 0 && diff > -30000 && S.armed && !S.firing) {\n    log('wn', '\\ud83d\\udcf1 \\u5c4f\\u5e55\\u5524\\u9192\\u540e\\u8865\\u53d1\\uff08\\u9519\\u8fc7\\u4e0d\\u8d85\\u8fc730\\u79d2\\uff09');\n    S.armed = false; S.firing = true;\n    document.getElementById('armBtn').textContent = '\\ud83d\\ude80 \\u542f\\u52a8\\u5b9a\\u65f6\\u62a2\\u573a';\n    document.getElementById('armBtn').className   = 'btn-go';\n    fireBooking().finally(() => { S.firing = false; });\n  }\n  if (S.armed && !wakeLock) acquireWakeLock();\n  tick();\n});\n\nfunction startTick() {\n  if (S.tick) clearInterval(S.tick);\n  S.tick = setInterval(tick, 500);\n  tick();\n}\n\nfunction tick() {\n  const now    = new Date();\n  const parts  = document.getElementById('openTime').value.split(':');\n  const lead   = parseInt(document.getElementById('leadMs').value) || 0;\n  const target = new Date();\n  target.setHours(+parts[0], +parts[1], 0, 0);\n  if (now >= target) target.setDate(target.getDate() + 1);\n\n  const diff = target - now - lead;\n  const h = Math.floor(diff / 3600000);\n  const m = Math.floor((diff % 3600000) / 60000);\n  const s = Math.floor((diff % 60000) / 1000);\n\n  const numEl = document.getElementById('cdNum');\n  const lblEl = document.getElementById('cdLbl');\n  const box   = document.getElementById('cdBox');\n\n  document.getElementById('barFill').style.width =\n    Math.max(0, 100 - diff / 864000 * 100) + '%';\n  document.getElementById('cdSub').textContent =\n    `\\u76ee\\u6807: ${fmt(targetDate())} \\u5468${WEEKDAYS[targetDate().getDay()]}`;\n\n  if (diff <= 0 && diff > -60000) {\n    numEl.textContent = '\\ud83d\\udd25 \\u5f00\\u62a2\\uff01'; numEl.className = 'cd-num g';\n    lblEl.textContent = '\\u6b63\\u5728\\u53d1\\u9001\\u8bf7\\u6c42...';\n    if (S.armed && !S.firing) {\n      S.armed = false; S.firing = true;\n      document.getElementById('armBtn').textContent = '\\ud83d\\ude80 \\u542f\\u52a8\\u5b9a\\u65f6\\u62a2\\u573a';\n      document.getElementById('armBtn').className   = 'btn-go';\n      releaseWakeLock();\n      fireBooking().finally(() => { S.firing = false; });\n    }\n    return;\n  } else if (diff <= 0) {\n    numEl.textContent = `${p2(h)}:${p2(m)}:${p2(s)}`;\n    numEl.className   = 'cd-num';\n    lblEl.textContent = '\\u8ddd\\u79bb\\u5f00\\u653e\\u8fd8\\u6709';\n    box.className     = 'cd-box';\n    return;\n  }\n\n  numEl.textContent = `${p2(h)}:${p2(m)}:${p2(s)}`;\n  if (diff < 60000) {\n    numEl.className = 'cd-num w'; lblEl.textContent = '\\u26a1 \\u5373\\u5c06\\u5f00\\u653e\\uff01'; box.className = 'cd-box soon';\n  } else if (diff < 300000) {\n    numEl.className = 'cd-num w'; lblEl.textContent = '\\u8ddd\\u79bb\\u5f00\\u653e\\u8fd8\\u6709'; box.className = 'cd-box live';\n  } else {\n    numEl.className = 'cd-num';\n    lblEl.textContent = S.armed ? '\\u23f3 \\u5df2\\u6b66\\u88c5\\uff0c\\u7b49\\u5f85\\u5f00\\u653e' : '\\u8ddd\\u79bb\\u5f00\\u653e\\u8fd8\\u6709';\n    box.className = S.armed ? 'cd-box live' : 'cd-box';\n  }\n}\n\nfunction toggleArm() {\n  if (!S.armed) {\n    if (!document.getElementById('token').value.trim()) { log('er','\\u274c \\u8bf7\\u5148\\u586b\\u5165 Token\\uff01'); return; }\n    if (!selected.size) { log('er','\\u274c \\u8bf7\\u5728\\u683c\\u5b50\\u91cc\\u9009\\u81f3\\u5c11\\u4e00\\u683c\\uff01'); return; }\n  }\n  S.armed = !S.armed;\n  const btn = document.getElementById('armBtn');\n  if (S.armed) {\n    const p = document.getElementById('openTime').value;\n    btn.textContent = '\\ud83d\\udd34 \\u5df2\\u6b66\\u88c5 \\u2014 \\u70b9\\u51fb\\u53d6\\u6d88'; btn.className = 'btn-go disarm';\n    acquireWakeLock();\n    log('ok', `\\u2705 \\u5b9a\\u65f6\\u5df2\\u542f\\u52a8\\uff01\\u5c06\\u5728 ${p} \\u81ea\\u52a8\\u5e76\\u53d1\\u62a2\\u573a`);\n    log('wn', `\\u5df2\\u9009 ${selected.size} \\u683c\\uff0c\\u6d89\\u53ca ${new Set([...selected].map(k=>k.split(/-(.+)/)[0])).size} \\u4e2a\\u573a\\u5730`);\n    log('wn', '\\u6536\\u5230\\u6210\\u529f\\u63d0\\u793a\\u540e\\u7acb\\u523b\\u5b8c\\u6210\\u9a8c\\u8bc1\\u7801+\\u652f\\u4ed8');\n  } else {\n    btn.textContent = '\\ud83d\\ude80 \\u542f\\u52a8\\u5b9a\\u65f6\\u62a2\\u573a'; btn.className = 'btn-go';\n    releaseWakeLock();\n    log('inf', '\\u5df2\\u53d6\\u6d88\\u5b9a\\u65f6');\n  }\n}\n\nasync function fireNow() {\n  if (S.firing) { log('wn','\\u6b63\\u5728\\u53d1\\u9001\\u4e2d...'); return; }\n  log('wn','\\u26a1 \\u7acb\\u5373\\u6d4b\\u8bd5\\uff08\\u4e0d\\u7b497:30\\uff09');\n  S.firing = true;\n  await fireBooking().finally(() => { S.firing = false; });\n}\n\nasync function fireBooking() {\n  const token = document.getElementById('token').value.trim();\n  if (!token)         { log('er','\\u274c Token \\u4e3a\\u7a7a\\uff01'); return; }\n  if (!selected.size) { log('er','\\u274c \\u8bf7\\u5728\\u683c\\u5b50\\u91cc\\u9009\\u81f3\\u5c11\\u4e00\\u683c\\uff01'); return; }\n  if (!D.loaded)      { log('er','\\u274c \\u8bf7\\u5148\\u67e5\\u8be2\\u7a7a\\u4f4d\\u52a0\\u8f7d\\u6570\\u636e\\uff01'); return; }\n\n  const date     = fmt(targetDate());\n  const nodeList = D.courtOrder.map(name => ({sitename: name, nodeid: D.courts[name]}));\n\n  const byCourt = {};\n  for (const key of selected) {\n    const dash  = key.indexOf('-');\n    const court = key.slice(0, dash);\n    const time  = key.slice(dash + 1);\n    const cell  = document.getElementById(`slot_${court}_${time.replace(':','')}`);\n    const fen   = cell ? parseInt(cell.dataset.fen || '4000') : 4000;\n    if (!byCourt[court]) byCourt[court] = [];\n    byCourt[court].push({ time, fen });\n  }\n\n  const courtList = Object.keys(byCourt);\n  log('inf', `\\ud83d\\udcc5 ${date}\\uff08+${S.dayOffset}\\uff09  \\ud83d\\udc65 ${S.people}\\u4eba  \\ud83c\\udfdf\\ufe0f \\u573a\\u5730: ${courtList.join(' ')}`);\n  log('inf', `\\ud83d\\ude80 \\u5e76\\u53d1\\u53d1\\u51fa ${courtList.length} \\u4e2a\\u8bf7\\u6c42...`);\n\n  const tasks = courtList.map(courtKey => {\n    const slots    = byCourt[courtKey].sort((a,b) => a.time.localeCompare(b.time));\n    const times    = slots.map(s => s.time);\n    const totalFen = slots.reduce((sum, s) => sum + s.fen, 0);\n    const courtIdx = D.courtOrder.indexOf(courtKey);\n    const coords   = times.map(t => `${courtIdx}-${D.slotIdx[t]}`);\n    log('inf', `  [${courtKey}] ${times.join(' ')} coords:${coords.join(',')} \\u00a5${totalFen/100}`);\n    const body = {\n      nodeList,\n      payprice:        String(totalFen),\n      isLastDay:       false,\n      appointmentDate: date,\n      timeList:        D.timeList,\n      coordinatesList: coords,\n      booktype:        2,\n      nodeid:          VENUE_ID,\n      childrennum:     String(S.people),\n      followList:      [],\n      txamt:           String(totalFen),\n      payway:          '77'\n    };\n    return sendOne(token, aesEncrypt(body), courtKey);\n  });\n\n  const results = await Promise.allSettled(tasks);\n  let anyOk = false;\n  results.forEach((r, i) => {\n    if (r.status === 'fulfilled' && r.value.ok) {\n      showToast('ok', '\\u2705 \\u9884\\u7ea6\\u6210\\u529f\\uff01'); log('ok', `\\ud83c\\udf89\\ud83c\\udf89 ${courtList[i]} \\u9884\\u7ea6\\u6210\\u529f\\uff01\\u5feb\\u53bbApp\\u5b8c\\u6210\\u9a8c\\u8bc1\\u7801\\u548c\\u652f\\u4ed8\\uff01`);\n      document.getElementById('cdBox').className = 'cd-box live';\n      anyOk = true;\n    }\n  });\n  if (!anyOk)\n    log('wn', '\\u6c47\\u603b: ' + results.map((r,i) =>\n      `${courtList[i]}:${r.status==='fulfilled' ? r.value.msg : '\\u7f51\\u7edc\\u5f02\\u5e38'}`\n    ).join(' | '));\n}\n\nasync function sendOne(token, encrypted, label) {\n  try {\n    const t0  = Date.now();\n    const res = await fetch(PROXY + API_BOOK, {\n      method:  'POST',\n      headers: { 'Content-Type': 'application/json', token },\n      body:    JSON.stringify({ item: encrypted })\n    });\n    const ms  = Date.now() - t0;\n    const raw = await res.text();\n    if (raw.trimStart().startsWith('<')) {\n      showToast('er', '\\u274c \\u9884\\u7ea6\\u5931\\u8d25'); log('er', `[${label}] \\u26a0\\ufe0f \\u670d\\u52a1\\u5668\\u8fd4\\u56deHTML\\uff08IP\\u9650\\u5236/token\\u5931\\u6548\\uff09${res.status} (${ms}ms)`);\n      return { ok: false, msg: 'HTML\\u54cd\\u5e94' };\n    }\n    let data = {};\n    try { data = JSON.parse(raw); } catch(_) {}\n    log('inf', `[${label}] HTTP ${res.status} (${ms}ms) \\u2192 ${raw.substring(0, 100)}`);\n    const ok = data.success === true || data.code === '200' || data.code === 200\n             || (typeof data.msg === 'string' && /\\u6210\\u529f/.test(data.msg));\n    return { ok, msg: data.message || data.msg || raw.substring(0, 60) };\n  } catch(e) {\n    showToast('er', '\\u274c \\u9884\\u7ea6\\u5931\\u8d25'); log('er', `[${label}] \\u274c ${e.message}`);\n    return { ok: false, msg: e.message };\n  }\n}\n\nfunction showToast(type, msg, dur) {\n  const el = document.getElementById('toast');\n  el.textContent = msg;\n  el.className = 'toast ' + type + ' show';\n  clearTimeout(el._t);\n  el._t = setTimeout(() => { el.className = 'toast'; }, dur || 3000);\n}\n\nfunction log(type, msg) {\n  const el  = document.getElementById('log');\n  const now = new Date();\n  const ts  = `${p2(now.getHours())}:${p2(now.getMinutes())}:${p2(now.getSeconds())}`;\n  const div = document.createElement('div');\n  div.className   = type;\n  div.textContent = `[${ts}] ${msg}`;\n  el.appendChild(div);\n  el.scrollTop = el.scrollHeight;\n  if (el.children.length > 150) el.removeChild(el.firstChild);\n}\n\n(function init() {\n  buildGrid();\n  initDayLabels();\n  startTick();\n  updateTarget();\n  updateSummary();\n\n  const saved = localStorage.getItem('cugb_token');\n  if (saved) document.getElementById('token').value = saved;\n  const savedOpenid = localStorage.getItem('cugb_openid');\n  if (savedOpenid) {\n    const savedName = localStorage.getItem('cugb_name');\n    if (savedName) document.getElementById('userName').textContent = savedName;\n  } else {\n    document.getElementById('userName').textContent = '';\n  }\n  if (savedOpenid && !saved) wxLoginAuto(savedOpenid);\n  document.getElementById('token').addEventListener('blur', function() {\n    if (this.value.trim()) localStorage.setItem('cugb_token', this.value.trim());\n    if (!localStorage.getItem('cugb_openid')) {\n      document.getElementById('userName').textContent = '';\n      localStorage.removeItem('cugb_name');\n    }\n  });\n\n  log('inf', 'v18.0 \\u2713  \\u52a8\\u6001\\u573a\\u6b21 | \\u53ef\\u89c6\\u5316\\u683c\\u5b50 | \\u53cc\\u6863\\u5b9a\\u4ef7 | WakeLock | \\u7a7a\\u4f4d\\u67e5\\u8be2 | \\u9ed8\\u8ba4\\u540e\\u5929');\n  log('inf', '\\ud83d\\udccb \\u6b65\\u9aa4: \\u2460 \\u586bToken \\u2192 \\u2461 \\u67e5\\u8be2\\u7a7a\\u4f4d \\u2192 \\u2462 \\u9009\\u683c\\u5b50 \\u2192 \\u2463 \\u542f\\u52a8\\u5b9a\\u65f6');\n  if (saved) fetchSchedule();\n})();\n</script>\n</body>\n</html>";

const WECHAT_UA = 'Mozilla/5.0 (Linux; Android 12; SM-G9910 Build/SP1A.210812.016; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/107.0.5304.141 Mobile Safari/537.36 XWEB/5235 MMWEBSDK/20230506 Mobile MicroMessenger/8.0.37.2380(0x2800253A) WeChat/arm64 Weixin NetType/WIFI Language/zh_CN ABI/arm64 miniProgram';

const SKIP = new Set([
  'host','cf-ray','cf-connecting-ip','cf-ipcountry',
  'cf-visitor','cf-worker','x-real-ip','x-forwarded-for','x-forwarded-proto',
  'content-length','transfer-encoding','accept-encoding',
]);

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // 根路径 → 工具页面
    if (request.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
      return new Response(HTML, {
        status: 200,
        headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' }
      });
    }

    // CORS 预检
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
        'Access-Control-Allow-Headers': '*',
        'Access-Control-Max-Age': '86400',
      }});
    }

    // 代理到真实服务器
    const targetUrl = 'https://bdtyg.cugb.edu.cn' + url.pathname + url.search;
    const fwdHeaders = new Headers();
    for (const [k, v] of request.headers)
      if (!SKIP.has(k.toLowerCase())) fwdHeaders.set(k, v);

    fwdHeaders.set('Origin',  'https://bdtyg.cugb.edu.cn');
    fwdHeaders.set('Referer', 'https://bdtyg.cugb.edu.cn/');
    fwdHeaders.set('User-Agent', WECHAT_UA);
    fwdHeaders.set('X-Requested-With', 'com.tencent.mm');

    let upstream;
    try {
      upstream = await fetch(targetUrl, {
        method: request.method,
        headers: fwdHeaders,
        body: ['GET','HEAD'].includes(request.method) ? undefined : request.body,
        redirect: 'follow',
      });
    } catch (err) {
      return new Response(
        JSON.stringify({ success: false, message: 'Worker上游错误: ' + err.message }),
        { status: 502, headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' } }
      );
    }

    const body = await upstream.arrayBuffer();
    return new Response(body, {
      status: upstream.status,
      statusText: upstream.statusText,
      headers: {
        'Content-Type': upstream.headers.get('Content-Type') || 'application/json',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': '*',
      }
    });
  }
};